import org.apache.commons.lang.StringUtils;

String generateUsername(String first, String last) {
  if (StringUtils.isBlank(first) || StringUtils.isBlank(last)) {
    return null;
  }
  String base = first.trim().substring(0, 1) + last.trim();
  return base.toLowerCase().replaceAll("[^a-z0-9]", "");
}

String username = generateUsername(identity.getFirstname(), identity.getLastname());
log.debug("Generated username for " + identity.getName() + ": " + username);
return username;
